<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
$admin = require_admin($pdo);
$type = (string)($_GET['type'] ?? 'all');
$status = (string)($_GET['status'] ?? '');
$q = trim((string)($_GET['q'] ?? ''));
if (!in_array($type, ['all','lost','found'], true)) $type = 'all';
$where = []; $params = [];
if ($type !== 'all') { $where[] = 'i.item_type=?'; $params[] = $type; }
if ($status !== '') { $where[] = 'i.status=?'; $params[] = $status; }
if ($q !== '') { $where[] = '(i.reference_code LIKE ? OR i.title LIKE ? OR i.location_found_or_lost LIKE ? OR i.category LIKE ?)'; $like = '%' . $q . '%'; array_push($params,$like,$like,$like,$like); }
$sql = 'SELECT i.*, u.full_name AS created_by_name FROM items i JOIN users u ON u.id=i.created_by';
if ($where) $sql .= ' WHERE ' . implode(' AND ', $where);
$sql .= ' ORDER BY i.created_at DESC LIMIT 500';
$stmt = $pdo->prepare($sql); $stmt->execute($params); $items = $stmt->fetchAll();
$logs = $pdo->query('SELECT l.*, u.full_name AS actor_name, u.username, u.student_id FROM activity_logs l LEFT JOIN users u ON u.id=l.actor_user_id ORDER BY l.activity_at DESC LIMIT 100')->fetchAll();
$counts = $pdo->query("SELECT COUNT(*) total, SUM(item_type='lost') lost_count, SUM(item_type='found') found_count, SUM(status='returned') returned_count FROM items")->fetch();
render_header('Reports and logs','reports');
?>
<div class="page-header"><div><div class="eyebrow"><span class="pulse-dot"></span> REPORTING &amp; ACCOUNTABILITY</div><h1>Reports &amp; activity logs</h1><p>Filter item records, export a CSV for school reporting, and review actions recorded by the system.</p></div><div class="header-actions"><a class="btn btn-primary" href="export_reports.php?<?= e(http_build_query(['type'=>$type,'status'=>$status,'q'=>$q])) ?>">↓ Export CSV</a></div></div>
<div class="stat-grid"><div class="stat-card"><div class="stat-top"><span class="stat-icon">▦</span></div><div class="stat-label">All item records</div><div class="stat-value"><?= number_format((int)$counts['total']) ?></div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon red">⌕</span></div><div class="stat-label">Lost reports</div><div class="stat-value"><?= number_format((int)$counts['lost_count']) ?></div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon">◇</span></div><div class="stat-label">Found items</div><div class="stat-value"><?= number_format((int)$counts['found_count']) ?></div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon green">✓</span></div><div class="stat-label">Returned items</div><div class="stat-value"><?= number_format((int)$counts['returned_count']) ?></div></div></div>
<section class="panel"><div class="panel-heading-row"><div><h2>Item report</h2><p>Up to 500 records per view/export.</p></div><span class="pill"><?= count($items) ?> record(s)</span></div><div class="panel-body"><div class="toolbar"><form class="search-form" method="get"><div class="search-input"><span>⌕</span><input type="search" name="q" value="<?= e($q) ?>" placeholder="Search title, reference, category, location…"></div><select class="filter-select" name="type"><option value="all">All types</option><option value="lost" <?= $type==='lost'?'selected':'' ?>>Lost</option><option value="found" <?= $type==='found'?'selected':'' ?>>Found</option></select><select class="filter-select" name="status"><option value="">All statuses</option><?php foreach (['open','matched','closed','available_for_claim','claim_under_review','returned'] as $s): ?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-outline btn-small">Filter</button></form></div><?php if (!$items): ?><div class="empty-state"><strong>No matching records</strong><p>Change the search or filter and try again.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Reference / Title</th><th>Type</th><th>Category</th><th>Location</th><th>Event date</th><th>Status</th><th>Posted by</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><span class="table-main"><?= e($item['title']) ?></span><span class="table-sub"><?= e($item['reference_code']) ?></span></td><td><?= e(ucfirst($item['item_type'])) ?></td><td><?= e($item['category']) ?></td><td><?= e($item['location_found_or_lost']) ?></td><td><?= e(date('M j, Y',strtotime($item['event_date']))) ?></td><td><span class="status-badge status-<?= e(status_class($item['status'])) ?>"><?= e(status_label($item['status'])) ?></span></td><td><?= e($item['created_by_name']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
<section class="panel items-management-panel"><div class="panel-heading-row"><div><h2>Recent activity log</h2><p>Shows who performed the action, what was changed, and when.</p></div><span class="pill">Latest 100</span></div><?php if (!$logs): ?><div class="empty-state"><strong>No activity yet</strong><p>Logins and important actions will appear here.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Date / time</th><th>Actor</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td><?= e(date('M j, Y · g:i A',strtotime($log['activity_at']))) ?></td><td><?= e($log['actor_name'] ?: 'Unrecognized / visitor') ?><span class="table-sub"><?= e($log['student_id'] ?: $log['username'] ?: '') ?></span></td><td><span class="table-main"><?= e(str_replace('_',' ',$log['action_name'])) ?></span></td><td><?= e($log['target_type'] ?: '—') ?><?= $log['target_id'] ? ' #' . (int)$log['target_id'] : '' ?></td><td><?= e($log['details'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<div class="page-footer-note">For privacy, activity logs should only be viewed by authorized staff and kept according to the school's approved retention policy.</div>
<?php render_footer(); ?>
